21	func (r *oneShotReader) Read(p []byte) (int, error) {
22		if r.done {
23			return 0, io.EOF
24		}
25		r.done = true
26		if len(r.data) == 0 {
27			return 0, r.err
28		}
29		n := copy(p, r.data)
30		return n, r.err
31	}
