257	// Only a fault already received wins. A content error found before the reader
258	// has reported any failure rejects the snapshot as invalid right away, without
259	// reading ahead to look for a fault.
260	func TestRestoreContentErrorBeforeFaultStaysInvalid(t *testing.T) {
261		index := txChain(t, []string{"a"}, []string{"b"})
