276	func TestRestoreReadFailureKeepsChainAndCursor(t *testing.T) {
277		index := txChain(t, []string{"a"}, []string{"b"}, []string{"c"})
278		first, err := index.QueryTxs(TxQuery{PageSize: 1})
279		if err != nil {
280			t.Fatal(err)
281		}
282		cursor := first.NextCursor
283		if cursor == "" {
284			t.Fatal("expected a continuation cursor")
285		}
286		blocks, byHash, tip := snapshot(index)
287	
288		err = index.Restore(&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF})
289		if !errors.Is(err, io.ErrUnexpectedEOF) || errors.Is(err, ErrInvalidSnapshot) {
290			t.Fatalf("err=%v, want a read failure distinct from ErrInvalidSnapshot", err)
291		}
