295		// must not be reported as ErrQueryChanged.
296		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
297		var all []TxHit
298		for _, page := range pages {
299			all = append(all, page.Hits...)
300		}
301		want := []TxHit{
302			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
303			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
