324		}
325		dupX := restoreIngestQuery(t, index, "x")
326		if !reflect.DeepEqual(dupX.Hits, []TxHit{
327			{Height: 1, BlockHash: "j1", TxID: "x", Position: 0},
328			{Height: 1, BlockHash: "j1", TxID: "x", Position: 2},
329		}) {
330			t.Fatalf("duplicate snapshot tx must keep both in-block positions: %+v", dupX.Hits)
331		}
332	
333		// A fresh export contains exactly the snapshot main chain: no height 3
334		// and no replaced hash anywhere in the bytes.
335		doc := mustRestoreIngestExport(t, index)
336		if doc.Version != 1 || doc.Tip != 2 || len(doc.Blocks) != 2 {
337			t.Fatalf("export after restore=%+v, want version 1, tip 2, two blocks", doc)
338		}
339		for i, want := range []struct {
340			height int64
341			hash   string
342			parent string
343			txs    []string
344		}{
345			{1, "j1", "g", []string{"x", "z", "x"}},
346			{2, "j2", "j1", []string{"y"}},
347		} {
348			got := doc.Blocks[i]
349			if got.Height != want.height || got.Hash != want.hash || got.Parent != want.parent ||
350				!reflect.DeepEqual(got.Txs, want.txs) {
351				t.Fatalf("exported block %d=%+v, want %+v", i+1, got, want)
352			}
353		}
354		raw := exportString(t, index)
355		for _, gone := range []string{"h1", "h2", "h3", `"c"`} {
356			if strings.Contains(raw, gone) {
357				t.Fatalf("export after restore still contains %q:\n%s", gone, raw)
358			}
359		}
360	
361		// Requests still parented by the pre-restore tip (h2) or by the block
362		// appended during the read (h3) follow the existing rejection rules and
363		// must not revive the replaced chain.
364		stateBlocks, stateByHash, stateTip := snapshot(index)
365		for _, stale := range []Block{
366			{Height: 3, Hash: "r3", Parent: "h2", Txs: []string{"r"}}, // parented by the old tip
367			{Height: 4, Hash: "r4", Parent: "h3", Txs: []string{"r"}}, // parented by the mid-read block
368		} {
369			if err := index.Append(stale); err == nil {
370				t.Fatalf("stale append %+v must be rejected after the restore", stale)
371			}
372			requireUnchanged(t, index, stateBlocks, stateByHash, stateTip)
373		}
374	
375		// Ingestion continues from the new chain tip and hash.
376		continued := Block{Height: 3, Hash: "k3", Parent: "j2", Txs: []string{"w"}}
377		if err := index.Append(continued); err != nil {
378			t.Fatalf("append continuing the snapshot chain: %v", err)
379		}
380		if index.Tip != 3 || index.Blocks[3].Hash != "k3" || index.Blocks[3].Parent != "j2" {
381			t.Fatalf("chain after continuation: tip=%d block3=%+v", index.Tip, index.Blocks[3])
382		}
383		gotW := restoreIngestQuery(t, index, "w")
384		if !reflect.DeepEqual(gotW.Hits, []TxHit{{Height: 3, BlockHash: "k3", TxID: "w", Position: 0}}) {
385			t.Fatalf("continued block transaction=%+v, want w@k3#0", gotW.Hits)
386		}
387		// A block still citing h3 (the vanished mid-read tip) cannot extend the
388		// chain even at the right height.
389		if err := index.Append(Block{Height: 4, Hash: "r4", Parent: "h3", Txs: []string{"r"}}); err == nil {
390			t.Fatal("append parented by the vanished h3 must be rejected")
391		}
392		if index.Tip != 3 || index.Blocks[3].Hash != "k3" {
393			t.Fatalf("rejected append altered the restored chain: tip=%d block3=%+v", index.Tip, index.Blocks[3])
394		}
395	}
396	
397	// After a legal append during the read window, an invalid block discovered
398	// only at the end of the input fails the restore with ErrInvalidSnapshot and
399	// leaves the old chain plus the appended block exactly as they were; the
400	// snapshot's valid prefix leaves nothing behind.
401	func TestRestoreRejectedByLastBlockKeepsIngestedChain(t *testing.T) {
402		index := buildRestoreIngestChain(t)
403		reader := newGatedReader(t, restoreIngestBrokenSnapshot, restoreIngestCutMarker)
404		restoreDone := make(chan error, 1)
405		go func() {
406			restoreDone <- index.Restore(reader)
407		}()
408		<-reader.entered
409		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
410			t.Fatalf("append while restore is reading: %v", err)
411		}
412		page := restoreIngestQuery(t, index)
413		if page.ToHeight != 3 || len(page.Hits) != 3 {
414			t.Fatalf("setup: appended block not visible during the read: %+v", page)
415		}
416	
417		close(reader.release)
418		if err := <-restoreDone; !errors.Is(err, ErrInvalidSnapshot) {
419			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
420		}
421	
422		// The old chain and the block ingested during the read both survive; no
423		// snapshot block was left behind.
424		wantIndex := chain(t, append(restoreIngestOldChainBlocks(), restoreIngestAppendedBlock())...)
425		if !reflect.DeepEqual(index.Blocks, wantIndex.Blocks) || !reflect.DeepEqual(index.ByHash, wantIndex.ByHash) || index.Tip != 3 {
426			t.Fatalf("chain after rejected restore:\nblocks=%v\nbyHash=%v tip=%d\nwant the old chain plus h3",
427				index.Blocks, index.ByHash, index.Tip)
428		}
429		for _, leaked := range []string{"j1", "j2"} {
430			if _, ok := index.ByHash[leaked]; ok {
431				t.Fatalf("snapshot hash %s from the valid prefix was left indexed", leaked)
432			}
433		}
434	
435		page = restoreIngestQuery(t, index)
436		wantHits := []TxHit{
437			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
438			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
439			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
440		}
441		if !reflect.DeepEqual(page.Hits, wantHits) || page.ToHeight != 3 {
442			t.Fatalf("query after rejected restore=%+v, want the complete old chain including h3", page)
443		}
444		if len(restoreIngestQuery(t, index, "x", "y", "z").Hits) != 0 {
445			t.Fatal("snapshot transactions leaked in after the rejected restore")
446		}
447	
448		// Export reflects the chain as extended by the mid-read append, with no
449		// snapshot hash or transaction in the document.
450		doc := mustRestoreIngestExport(t, index)
451		if doc.Version != 1 || doc.Tip != 3 || len(doc.Blocks) != 3 {
452			t.Fatalf("export after rejected restore=%+v, want version 1, tip 3, three blocks", doc)
453		}
454		for i, want := range []struct {
455			height int64
456			hash   string
457			parent string
458			txs    []string
459		}{
460			{1, "h1", "g", []string{"a"}},
461			{2, "h2", "h1", []string{"b"}},
462			{3, "h3", "h2", []string{"c"}},
463		} {
464			got := doc.Blocks[i]
465			if got.Height != want.height || got.Hash != want.hash || got.Parent != want.parent ||
466				!reflect.DeepEqual(got.Txs, want.txs) {
467				t.Fatalf("exported block %d=%+v, want %+v", i+1, got, want)
468			}
469		}
470		if raw := exportString(t, index); strings.Contains(raw, "j1") || strings.Contains(raw, "j2") {
471			t.Fatalf("export after rejected restore contains snapshot hashes:\n%s", raw)
472		}
473	}
474	
475	// gatedTailFaultReader delivers the prefix, parks until release, then hands
476	// over the remaining bytes together with fault on the first read after the
477	// gate and the fault on every later read. It models a stream whose storage
478	// fails once the restore is allowed to run to the end, even when the buffered
479	// tail already completes the document.
480	type gatedTailFaultReader struct {
481		data    []byte
482		prefix  int
483		off     int
484		fault   error
485		entered chan struct{}
486		release chan struct{}
487		parked  bool
488		once    sync.Once
489	}
490	
491	func newGatedTailFaultReader(t *testing.T, data, cutMarker string, fault error) *gatedTailFaultReader {
492		t.Helper()
493		prefix := strings.Index(data, cutMarker)
494		if prefix <= 0 {
495			t.Fatalf("test setup: cut marker %q not found in %q", cutMarker, data)
496		}
497		if fault == nil {
498			t.Fatal("test setup: gated tail fault reader requires a fault")
499		}
500		return &gatedTailFaultReader{
501			data:    []byte(data),
502			prefix:  prefix,
503			fault:   fault,
504			entered: make(chan struct{}),
505			release: make(chan struct{}),
506		}
507	}
508	
509	func (r *gatedTailFaultReader) Read(p []byte) (int, error) {
510		if r.off < r.prefix {
511			n := copy(p, r.data[r.off:r.prefix])
512			r.off += n
513			return n, nil
514		}
515		if !r.parked {
516			r.parked = true
517			r.once.Do(func() { close(r.entered) })
518			<-r.release
519		}
520		if r.off < len(r.data) {
521			n := copy(p, r.data[r.off:])
522			r.off += n
523			// Bytes and fault in one read, exactly as a failing storage read can
524			// deliver them; snapshotReader withholds the fault until next time.
525			return n, r.fault
526		}
527		return 0, r.fault
528	}
529	
530	// After a legal append during the read window, a read fault reported at the
531	// end of the input — together with the tail bytes of an otherwise complete
532	// snapshot — fails the restore as a read failure carrying the recognizable
533	// original fault (never ErrInvalidSnapshot) and leaves the old chain plus the
534	// appended block in effect, in queries and in export.
535	func TestRestoreReadFaultAfterIngestionKeepsChainAndFault(t *testing.T) {
536		index := buildRestoreIngestChain(t)
537		// The valid snapshot completes in the faulted tail, proving a read
538		// failure outranks an already-complete document rather than applying it.
539		reader := newGatedTailFaultReader(t, restoreIngestSnapshot, restoreIngestCutMarker, errStorageOffline)
540		done := make(chan error, 1)
541		go func() {
542			done <- index.Restore(reader)
543		}()
544		<-reader.entered
545		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
546			t.Fatalf("append while restore is reading: %v", err)
547		}
548		page := restoreIngestQuery(t, index)
549		if page.ToHeight != 3 || len(page.Hits) != 3 {
550			t.Fatalf("setup: appended block not visible during the read: %+v", page)
551		}
552	
553		close(reader.release)
554		err := <-done
555		if err == nil {
556			t.Fatal("restore with a faulted tail must fail")
557		}
558		if errors.Is(err, ErrInvalidSnapshot) {
559			t.Fatalf("err=%v, a read fault must not be reported as ErrInvalidSnapshot", err)
560		}
561		if !errors.Is(err, errStorageOffline) {
562			t.Fatalf("err=%v, caller must still errors.Is the original fault", err)
563		}
564		if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
565			t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
566		}
567	
568		// The old chain and the block ingested during the read both survive; the
569		// complete, valid-looking snapshot is not applied and leaves nothing.
570		wantIndex := chain(t, append(restoreIngestOldChainBlocks(), restoreIngestAppendedBlock())...)
571		if !reflect.DeepEqual(index.Blocks, wantIndex.Blocks) || !reflect.DeepEqual(index.ByHash, wantIndex.ByHash) || index.Tip != 3 {
572			t.Fatalf("chain after read fault:\nblocks=%v\nbyHash=%v tip=%d\nwant the old chain plus h3",
573				index.Blocks, index.ByHash, index.Tip)
574		}
575		for _, leaked := range []string{"j1", "j2"} {
576			if _, ok := index.ByHash[leaked]; ok {
577				t.Fatalf("snapshot hash %s was left indexed after the read fault", leaked)
578			}
579		}
580		page = restoreIngestQuery(t, index)
581		if !reflect.DeepEqual(page.Hits, []TxHit{
582			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
583			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
584			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
585		}) || page.ToHeight != 3 {
586			t.Fatalf("query after read fault=%+v, want the complete old chain including h3", page)
587		}
588		doc := mustRestoreIngestExport(t, index)
589		if doc.Version != 1 || doc.Tip != 3 || len(doc.Blocks) != 3 {
590			t.Fatalf("export after read fault=%+v, want version 1, tip 3, three blocks", doc)
591		}
592		if doc.Blocks[2].Hash != "h3" || doc.Blocks[2].Parent != "h2" {
593			t.Fatalf("export after read fault must end at the appended h3: %+v", doc.Blocks[2])
594		}
595		if raw := exportString(t, index); strings.Contains(raw, "j1") || strings.Contains(raw, "j2") {
596			t.Fatalf("export after read fault contains snapshot hashes:\n%s", raw)
597		}
598	}
